#!/usr/bin/env node
/**
 * Build the browser half of the bundle.
 *
 * The DSH client loader expects exactly one artifact per package: a file that
 * calls `window.__ModuleLoader__.load({ id, factory })` and whose factory
 * returns `{ inject, apply }`. Our sources live under `src/client/` as normal
 * ES modules, so this script bundles them into that shape with esbuild.
 *
 * Usage:
 *   node scripts/build-client.mjs            write client.js + client.js.map
 *   node scripts/build-client.mjs --watch    rebuild on change (page HMR follows)
 *   node scripts/build-client.mjs --check    fail when the committed artifact is stale
 *
 * The banner and footer are esbuild options rather than post-processing so the
 * source map keeps pointing at the original source lines.
 */
import { build, context } from 'esbuild'
import { readFile, writeFile } from 'node:fs/promises'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const manifest = JSON.parse(await readFile(path.join(root, 'package.json'), 'utf8'))
const packageId = manifest.name
const artifactFile = 'client.js'
const mapFile = `${artifactFile}.map`
const artifactPath = path.join(root, artifactFile)
const mapPath = path.join(root, mapFile)

const args = new Set(process.argv.slice(2))
const watch = args.has('--watch')
const check = args.has('--check')
const unknown = [...args].filter((arg) => arg !== '--watch' && arg !== '--check')
if (unknown.length > 0) {
  console.error(`unknown option(s): ${unknown.join(', ')}`)
  process.exit(2)
}

const banner = `/* generated by scripts/build-client.mjs — edit src/ instead */
window.__ModuleLoader__.load({
  id: ${JSON.stringify(packageId)},
  factory: (require) => {
    var module = { exports: {} };
    var exports = module.exports;
`

const footer = `
    return module.exports;
  },
})
`

/** @type {import('esbuild').BuildOptions} */
const options = {
  absWorkingDir: root,
  entryPoints: ['src/client-entry.js'],
  outfile: artifactFile,
  bundle: true,
  format: 'cjs',
  platform: 'neutral',
  target: 'es2022',
  external: ['react'],
  loader: { '.css': 'text' },
  charset: 'utf8',
  legalComments: 'none',
  sourcemap: true,
  sourcesContent: true,
  logLevel: 'silent',
  banner: { js: banner },
  footer: { js: footer },
}

/**
 * Reject an artifact that would not load, or a map that points outside the
 * sources we build from. The artifact contract is what the loader validates, so
 * the build is the right place to catch a broken wrapper.
 * @param {string} text
 * @param {string | undefined} mapText
 */
function assertArtifact(text, mapText) {
  const problems = []
  if (!text.startsWith('/* generated by scripts/build-client.mjs')) problems.push('missing generated banner')
  if (!text.includes('window.__ModuleLoader__.load({')) problems.push('missing __ModuleLoader__.load call')
  if (!text.includes(`id: ${JSON.stringify(packageId)}`)) problems.push('artifact id does not match the package name')
  if (!text.includes('return module.exports;')) problems.push('missing factory return')
  if (!text.trimEnd().endsWith('//# sourceMappingURL=client.js.map')) problems.push('missing sourceMappingURL')
  if (!text.includes('require("react")')) problems.push('react is not kept external')
  if (mapText !== undefined) {
    /** @type {{sources?: string[]}} */
    const map = JSON.parse(mapText)
    const sources = map.sources ?? []
    if (sources.length === 0) problems.push('source map has no sources')
    if (sources.some((source) => source.includes('node_modules'))) problems.push('source map reaches into node_modules')
    if (!sources.some((source) => source.includes('src/'))) problems.push('source map does not point at src/')
  }
  if (problems.length > 0) {
    console.error(`artifact check failed:\n  - ${problems.join('\n  - ')}`)
    process.exit(1)
  }
}

if (check) {
  const result = await build({ ...options, write: false })
  const outputs = new Map(result.outputFiles.map((file) => [path.basename(file.path), file.text]))
  let stale = false
  for (const [name, expected] of [[artifactFile, outputs.get(artifactFile)], [mapFile, outputs.get(mapFile)]]) {
    if (expected === undefined) {
      console.error(`build produced no ${name}`)
      process.exit(1)
    }
    let actual
    try {
      actual = await readFile(path.join(root, name), 'utf8')
    } catch {
      actual = ''
    }
    if (actual !== expected) {
      stale = true
      console.error(`${name} is stale; run npm run build`)
    }
  }
  if (stale) process.exit(1)
  assertArtifact(outputs.get(artifactFile), outputs.get(mapFile))
  console.log('client.js and client.js.map are up to date')
} else if (watch) {
  const ctx = await context({
    ...options,
    plugins: [{
      name: 'report',
      setup(builder) {
        builder.onEnd((result) => {
          if (result.errors.length > 0) {
            console.error('build failed')
            return
          }
          console.log(`${new Date().toLocaleTimeString()} built client.js`)
        })
      },
    }],
  })
  await ctx.watch()
  assertArtifact(await readFile(artifactPath, 'utf8'))
  console.log(`watching src/ for ${packageId}; the page hot-reloads on rebuild`)
} else {
  const result = await build(options)
  if (result.errors.length > 0) process.exit(1)
  const artifact = await readFile(artifactPath, 'utf8')
  const map = await readFile(mapPath, 'utf8')
  assertArtifact(artifact, map)
  const lines = artifact.split('\n').length - 1
  console.log(`built ${artifactFile} (${lines} lines, ${Math.round(artifact.length / 1024)} KiB) from src/client-entry.js`)
}
